"""`lifeos commands`: docs/COMMANDS.md generated from the argument parser, so the list of commands cannot go stale."""


def _top(parser):
    for action in parser._actions:
        choices = getattr(action, "choices", None)
        if choices and "task" in choices:
            return action
    raise ValueError("no sub-commands found")


def render(parser):
    action = _top(parser)
    helps = {a.dest: (a.help or "") for a in action._choices_actions}
    lines = ["# Commands", "",
             "Generated by `lifeos commands --out docs/COMMANDS.md`; a test fails when this page is stale. "
             "`lifeos <command> --help` has the full detail.", "",
             "| Command | What it does | Options |", "|---|---|---|"]
    for name in sorted(action.choices):
        sub = action.choices[name]
        options = sorted({o for a in sub._actions for o in a.option_strings if o.startswith("--") and o != "--help"})
        text = " ".join(helps.get(name, "").split()).replace("|", "/")
        lines.append(f"| `lifeos {name}` | {text} | {' '.join(f'`{o}`' for o in options)} |")
    return chr(10).join(lines) + chr(10)
